def ceil_root(p, a, b):
    lo, hi = 0, 1
    while pow(hi, b) < pow(p, a):
        hi *= 2
    while lo < hi:
        mid = (lo + hi) // 2
        if pow(mid, b) >= pow(p, a):
            hi = mid
        else:
            lo = mid + 1
    return lo

def is_prime(m):
    if m < 2:
        return False
    i = 2
    while i * i <= m:
        if m % i == 0:
            return False
        i += 1
    return True

def verify(witness):
    primes = witness['primes']
    for q in primes:
        if not is_prime(q):
            raise ValueError(('not prime', q))
    for (a, b) in witness['c_values']:
        if 2 * a <= b:
            raise ValueError(('c must exceed 1/2', a, b))
    for p in primes:
        for (a, b) in witness['c_values']:
            M = ceil_root(p, a, b)
            if not (pow(M - 1, b) < pow(p, a) <= pow(M, b)):
                raise ValueError(('ceil check failed', p, a, b))
            for n in range(0, p + M + 1):
                lo = n + 1
                hi = n + M
                found = False
                for x in range(lo, hi):
                    if x % p == 0:
                        continue
                    for y in range(lo, hi):
                        if (x * y) % p == 1:
                            found = True
                            break
                    if found:
                        break
                if not found:
                    raise ValueError(('counterexample', p, a, b, n))
    return True
